#include "games/ravenloft/data/GraphicsDecode.h"
#include "games/ravenloft/data/Binary.h"
#include "games/ravenloft/data/Lzss.h"
#include <algorithm>
#include <stdexcept>
namespace ravenloft::data {
static void expectEh(std::span<const std::uint8_t> raw,std::uint8_t type){if(raw.size()<7||raw[0]!='E'||raw[1]!='H'||raw[2]!=type)throw std::runtime_error("Unexpected EH resource type");}
IndexedImage decodeBitmapType1(std::span<const std::uint8_t> raw){expectEh(raw,1);if(raw.size()<13)throw std::runtime_error("Bitmap payload too small");auto rows=u16(raw,5),strips=u16(raw,7);auto byteWidth=raw[9],key=raw[10],mode=raw[11];auto width=std::uint16_t(byteWidth)*8u;auto height=std::uint32_t(rows)*strips;if(!width||!height||height>65535)throw std::runtime_error("Invalid bitmap dimensions");std::vector<std::uint8_t> dec;if(mode==3)dec=lzssDecode(raw.subspan(13),std::size_t(width)*height);else if(mode==0){requireRange(raw,13,std::size_t(width)*height,"Bitmap pixels");dec.assign(raw.begin()+13,raw.begin()+13+std::size_t(width)*height);}else throw std::runtime_error("Unsupported bitmap compression");IndexedImage im;im.width=width;im.height=static_cast<std::uint16_t>(height);im.left=0;im.right=static_cast<std::int16_t>(width-1);im.top=0;im.bottom=static_cast<std::int16_t>(height-1);im.pixels=std::move(dec);im.alpha.resize(im.pixels.size());for(std::size_t i=0;i<im.pixels.size();++i)im.alpha[i]=(im.pixels[i]==key?0:255);return im;}
IndexedImage decodeTextureType6(std::span<const std::uint8_t> raw){expectEh(raw,6);auto size=u16(raw,5);if(size!=4096&&size!=8192)throw std::runtime_error("Unexpected type-6 texture size");auto dec=lzssDecode(raw.subspan(7),size);IndexedImage im;im.width=64;im.height=static_cast<std::uint16_t>(size/64);im.left=0;im.right=63;im.top=0;im.bottom=static_cast<std::int16_t>(im.height-1);im.pixels.resize(size);im.alpha.assign(size,255);/* Original payload is 64 columns, each height bytes; transpose to row-major. */for(std::size_t x=0;x<64;++x)for(std::size_t y=0;y<im.height;++y)im.pixels[y*64+x]=dec[x*im.height+y];return im;}
IndexedImage decodeSpriteType7(std::span<const std::uint8_t> raw){expectEh(raw,7);auto size=u16(raw,5);auto d=lzssDecode(raw.subspan(7),size);if(d.size()<10)throw std::runtime_error("Sprite payload too small");IndexedImage im;im.width=u16(d,0);im.height=128;im.left=i16(d,2);im.right=i16(d,4);im.top=i16(d,6);im.bottom=i16(d,8);if(!im.width||im.width>1024)throw std::runtime_error("Invalid sprite width");im.pixels.assign(std::size_t(im.width)*im.height,0);im.alpha.assign(im.pixels.size(),0);auto left=u16(d,2),right=u16(d,4);if(right<left)return im;if(right>=im.width)throw std::runtime_error("Invalid sprite bounds");for(std::size_t x=left;x<=right;++x){std::size_t p=u16(d,10+2*(x-left));for(;;){auto end=u16(d,p);p+=2;if(end==0)break;auto off=i16(d,p);auto start=u16(d,p+2);p+=4;if((end&1)||(start&1))throw std::runtime_error("Odd sprite scan coordinate");start/=2;end/=2;if(start>=end||end>128)throw std::runtime_error("Invalid sprite scan span");for(std::size_t y=start;y<end;++y){auto q=std::int64_t(off)+std::int64_t(y);if(q<0||std::size_t(q)>=d.size())throw std::runtime_error("Sprite pixel offset out of range");auto idx=std::size_t(y)*im.width+x;im.pixels[idx]=d[std::size_t(q)];im.alpha[idx]=255;}}}return im;}
}
